type SupplierMap = Record<string, { _id: Types.ObjectId; name: string; city: string; country: string; postalCode?: string | null; address?: string | null }>;

async function quoteAt(organizationId: Types.ObjectId, req: ShipmentRequest, at: Date, shipmentId: Types.ObjectId | undefined, userId: Types.ObjectId) {
  const adapters = SIM_PROFILES.map((p) => new SimulatedCarrierAdapter(p, () => at));
  const quotes: NormalizedQuote[] = (await Promise.all(adapters.map((a) => a.getQuotes(req)))).flat();
  const qrId = new Types.ObjectId();
  await QuoteRequest.collection.insertOne({
    _id: qrId,
    organizationId,
    shipmentId,
    request: { ...req, origin: { ...req.origin }, destination: { ...req.destination } },
    providers: SIM_PROFILES.map((p) => ({
      carrierCode: p.code, carrierName: p.name, provider: 'fluxora-simulator', mode: 'SIMULATED', status: 'OK',
      quoteCount: quotes.filter((q) => q.carrierCode === p.code).length, durationMs: 3, fromCache: false,
    })),
    createdBy: userId,
    createdAt: at,
  });
  const docs = quotes.map((q) => ({
    _id: new Types.ObjectId(),
    organizationId,
    quoteRequestId: qrId,
    shipmentId,
    carrierCode: q.carrierCode,
    carrierName: q.carrierName,
    serviceCode: q.serviceCode,
    serviceName: q.serviceName,
    serviceLevel: q.serviceLevel,
    currency: q.currency,
    totalMinor: q.totalMinor,
    breakdown: q.breakdown,
    transitDays: q.transitDays,
    estimatedDeliveryDate: q.estimatedDeliveryDate ? new Date(q.estimatedDeliveryDate) : undefined,
    billableWeightKg: q.billableWeightKg,
    volumetricWeightKg: q.volumetricWeightKg ?? undefined,
    constraints: q.constraints,
    provenance: { ...q.provenance, retrievedAt: new Date(q.provenance.retrievedAt), validUntil: q.provenance.validUntil ? new Date(q.provenance.validUntil) : undefined },
    eligibility: checkEligibility(q, req, at),
    reliability: { sampleSize: 0, minSamples: 5 },
    createdAt: at,
  }));
  await CarrierQuote.collection.insertMany(docs);
  return docs;
}

interface ShipmentPlan {
  ref: string;
  lane: Lane;
  carrier: CarrierCode;
  createdAt: Date;
  /** null = still planning; 'QUOTED' = offer selected, not booked */
  stage: 'DRAFT' | 'QUOTED' | 'BOOKED';
  outcome?: SimOutcome;
  purchaseOrder?: { _id: Types.ObjectId; poNumber: string; lines: { _id: Types.ObjectId; description: string; quantity: number; sku?: string | null; unitOfMeasure?: string | null }[] };
  cancelled?: boolean;
  /** Booked offline and tracked manually; last update days ago (demonstrates overdue / stuck alerts). */
  manualStuck?: boolean;
}

async function createDemoShipment(organizationId: Types.ObjectId, userId: Types.ObjectId, suppliers: SupplierMap, plan: ShipmentPlan) {
  const s = suppliers[plan.lane.supplierRef]!;
  const { lane } = plan;
  const req: ShipmentRequest = {
    origin: { city: s.city, postalCode: s.postalCode ?? undefined, country: s.country },
    destination: { city: lane.destination.city, postalCode: lane.destination.postalCode, country: lane.destination.country },
    shipmentType: lane.shipmentType,
    packageCount: lane.packageCount,
    actualWeightKg: lane.weightKg,
    lengthCm: lane.dims[0], widthCm: lane.dims[1], heightCm: lane.dims[2],
    insuranceRequired: false,
    specialHandling: [],
    currency: lane.currency,
    shipDate: plan.createdAt,
  };
  const shipmentId = new Types.ObjectId();
  const weight = calculateBillableWeight({ actualWeightKg: lane.weightKg, packageCount: lane.packageCount, lengthCm: lane.dims[0], widthCm: lane.dims[1], heightCm: lane.dims[2], divisor: 5000 });
  const base = {
    _id: shipmentId,
    organizationId,
    reference: plan.ref,
    purchaseOrderId: plan.purchaseOrder?._id,
    purchaseOrderNumber: plan.purchaseOrder?.poNumber,
    origin: { name: s.name, address: s.address ?? undefined, city: s.city, postalCode: s.postalCode ?? undefined, country: s.country },
    destination: lane.destination,
    shipmentType: lane.shipmentType,
    packageCount: lane.packageCount,
    actualWeightKg: lane.weightKg,
    lengthCm: lane.dims[0], widthCm: lane.dims[1], heightCm: lane.dims[2],
    volumetricWeightKg: weight.volumetricWeightKg ?? undefined,
    billableWeightKg: weight.billableWeightKg,
    servicePreference: lane.level,
    insuranceRequired: false,
    specialHandling: [],
    currency: lane.currency,
    items: plan.purchaseOrder
      ? plan.purchaseOrder.lines.map((l) => ({ poLineId: l._id, sku: l.sku ?? undefined, description: l.description, quantity: l.quantity, unitOfMeasure: l.unitOfMeasure ?? undefined }))
      : [],
    contentsDescription: plan.purchaseOrder ? plan.purchaseOrder.lines.map((l) => `${l.quantity} × ${l.description}`).join('; ').slice(0, 500) : 'Mixed merchandise (demo)',
    specUpdatedAt: new Date(0),
    trackingMode: 'NONE',
    createdBy: userId,
    isDemo: true,
    createdAt: plan.createdAt,
    updatedAt: plan.createdAt,
    __v: 0,
  };
  const events: Record<string, unknown>[] = [];
  const ev = (e: Record<string, unknown>) =>
    events.push({ _id: new Types.ObjectId(), organizationId, shipmentId, recordedAt: e.occurredAt, isException: false, ...e });
  ev({ type: 'CREATED', description: plan.purchaseOrder ? `Shipment created from purchase order ${plan.purchaseOrder.poNumber}` : 'Shipment created', occurredAt: plan.createdAt, newStatus: 'DRAFT', source: { type: 'USER', isSimulated: false }, actorId: userId, actorName: 'Alex Morgan (Demo Admin)' });

  if (plan.stage === 'DRAFT') {
    await Shipment.collection.insertOne({ ...base, status: 'DRAFT', statusChangedAt: plan.createdAt });
    await ShipmentEvent.collection.insertMany(events);
    return;
  }

  const quoteAtTime = new Date(plan.createdAt.getTime() + 20 * 60_000);
  const quotes = await quoteAt(organizationId, { ...req, servicePreference: lane.level }, quoteAtTime, shipmentId, userId);
  const eligible = quotes.filter((q) => q.eligibility.eligible);
  const chosen = eligible.find((q) => q.carrierCode === plan.carrier) ?? eligible.sort((a, b) => a.totalMinor - b.totalMinor)[0];
  if (!chosen) throw new Error(`No eligible simulated offer for ${plan.ref}`);
  const selectedAt = new Date(quoteAtTime.getTime() + 15 * 60_000);
  ev({ type: 'QUOTE_SELECTED', description: `Selected ${chosen.carrierName} ${chosen.serviceName} (simulated offer)`, occurredAt: selectedAt, previousStatus: 'DRAFT', newStatus: 'QUOTED', source: { type: 'USER', isSimulated: true }, actorId: userId, actorName: 'Alex Morgan (Demo Admin)' });

  const selection = {
    selectedQuoteId: chosen._id,
    carrierCode: chosen.carrierCode,
    carrierName: chosen.carrierName,
    serviceName: chosen.serviceName,
    serviceLevel: chosen.serviceLevel,
    quoteSourceType: 'SIMULATED',
    quoteIsSimulated: true,
    freightCostMinor: chosen.totalMinor,
    expectedDeliveryDate: chosen.estimatedDeliveryDate,
  };

  if (plan.stage === 'QUOTED') {
    await Shipment.collection.insertOne({ ...base, ...selection, status: 'QUOTED', statusChangedAt: selectedAt, updatedAt: selectedAt });
    await ShipmentEvent.collection.insertMany(events);
    return;
  }

  const bookedAt = new Date(selectedAt.getTime() + 30 * 60_000);
  const trackingNumber = `SIM${String(Math.floor(seededUnit(plan.ref) * 1e10)).padStart(10, '0')}`;
  const bookingReference = `SIM-BK-${chosen.carrierCode}-${plan.ref.slice(-6)}`;
  ev({ type: 'BOOKED', description: `Simulated booking ${bookingReference} created (no real carrier booking)`, occurredAt: bookedAt, previousStatus: 'QUOTED', newStatus: 'BOOKED', source: { type: 'SIMULATED', provider: 'fluxora-simulator', isSimulated: true }, actorId: userId, actorName: 'Alex Morgan (Demo Admin)', metadata: { bookingReference, trackingNumber } });

  let status: ShipmentStatus = 'BOOKED';
  let statusChangedAt = bookedAt;
  let pickedUpAt: Date | undefined;
  let deliveredAt: Date | undefined;
  let lastTrackingUpdateAt: Date | undefined;
  let lastKnownLocation: string | undefined;
  let step = 0;

  if (plan.manualStuck) {
    const at = new Date(bookedAt.getTime() + DAY_MS);
    ev({ type: 'STATUS_CHANGE', description: 'Carrier confirmed departure from origin terminal (entered manually)', occurredAt: at, location: { city: s.city, country: s.country }, previousStatus: 'BOOKED', newStatus: 'IN_TRANSIT', source: { type: 'USER', isSimulated: false }, actorId: userId, actorName: 'Sam Rivera (Demo Member)' });
    await Shipment.collection.insertOne({
      ...base, ...selection, status: 'IN_TRANSIT', statusChangedAt: at, pickedUpAt: at,
      booking: { reference: `DEMO-MANUAL-${plan.ref.slice(-4)}`, bookedAt, provider: 'manual', isSimulated: false, cancellable: true },
      trackingMode: 'MANUAL', lastTrackingUpdateAt: at, lastKnownLocation: `${s.city}, ${s.country}`, updatedAt: at,
    });
    await ShipmentEvent.collection.insertMany(events);
    return;
  }

  if (plan.cancelled) {
    const at = new Date(bookedAt.getTime() + 3 * HOUR_MS);
    ev({ type: 'CANCELLED', description: `Simulated booking ${bookingReference} cancelled. Reason: supplier delayed production`, occurredAt: at, previousStatus: 'BOOKED', newStatus: 'CANCELLED', source: { type: 'USER', isSimulated: true }, actorId: userId });
    status = 'CANCELLED';
    statusChangedAt = at;
  } else {
    const steps = planSimulatedJourney({
      trackingNumber,
      bookedAt,
      expectedDeliveryDate: chosen.estimatedDeliveryDate,
      origin: req.origin,
      destination: req.destination,
      simulationOutcome: plan.outcome ?? 'ON_TIME',
    });
    steps.forEach((st, i) => {
      if (st.at > NOW.getTime()) return;
      const at = new Date(st.at);
      const canMove = !!st.status && st.status !== status && canTransitionShipment(status, st.status);
      ev({
        type: canMove ? 'STATUS_CHANGE' : 'TRACKING',
        description: st.description,
        occurredAt: at,
        location: { city: st.city, country: st.country },
        previousStatus: canMove ? status : undefined,
        newStatus: canMove ? st.status : undefined,
        source: { type: 'SIMULATED', provider: 'fluxora-simulator', isSimulated: true },
        externalEventId: `${trackingNumber}:${i}`,
        isException: !!st.isException,
      });
      if (canMove) {
        status = st.status!;
        statusChangedAt = at;
        if (!pickedUpAt && ['PICKED_UP', 'IN_TRANSIT', 'OUT_FOR_DELIVERY', 'DELIVERED'].includes(st.status!)) pickedUpAt = at;
        if (st.status === 'DELIVERED') deliveredAt = at;
      }
      lastTrackingUpdateAt = at;
      lastKnownLocation = [st.city, st.country].filter(Boolean).join(', ');
      step = i + 1;
    });
  }

  await Shipment.collection.insertOne({
    ...base,
    ...selection,
    status,
    statusChangedAt,
    booking: { reference: bookingReference, bookedAt, provider: 'fluxora-simulator', isSimulated: true, cancellable: true },
    trackingNumber,
    trackingMode: 'SIMULATED',
    simulation: { nextStep: step, outcome: plan.outcome ?? 'ON_TIME' },
    pickedUpAt,
    deliveredAt,
    lastTrackingUpdateAt,
    lastTrackingPollAt: lastTrackingUpdateAt,
    lastKnownLocation,
    cancelledAt: status === 'CANCELLED' ? statusChangedAt : undefined,
    updatedAt: statusChangedAt,
  });
  await ShipmentEvent.collection.insertMany(events);
}

async function seedDemoOrg(organizationId: Types.ObjectId, adminId: Types.ObjectId, memberId: Types.ObjectId) {
  const supplierDocs = await Supplier.insertMany(SUPPLIERS.map((s) => ({ ...s, organizationId, isDemo: true })));
  const suppliers: SupplierMap = Object.fromEntries(supplierDocs.map((d) => [d.supplierRef, d.toObject()]));
  const productDocs = await Product.insertMany(PRODUCTS.map((p) => ({ ...p, organizationId, isDemo: true, description: `${p.name} — fictional demo catalogue item` })));
  const product = (sku: string) => productDocs.find((p) => p.sku === sku)!;

  // ---------------- Purchase orders ----------------
  type PoSpec = {
    supplierRef: string; status: PoStatus; orderDaysAgo: number; currency: Currency; destination: typeof WAREHOUSE_US;
    lines: { sku: string; qty: number; price?: number }[]; taxRateBps?: number; charges?: number; receivedFraction?: number; notes?: string;
  };
  const poSpecs: PoSpec[] = [
    { supplierRef: 'SUP-SZX-01', status: 'DRAFT', orderDaysAgo: 1, currency: 'USD', destination: WAREHOUSE_US, lines: [{ sku: 'EL-USB-C-HUB', qty: 400 }, { sku: 'EL-BT-SPK-02', qty: 150 }], notes: 'Q4 restock — awaiting final quantities' },
    { supplierRef: 'SUP-SGN-01', status: 'DRAFT', orderDaysAgo: 2, currency: 'USD', destination: WAREHOUSE_US, lines: [{ sku: 'HT-THROW-LIN', qty: 300 }, { sku: 'HT-CUSH-COV', qty: 600 }] },
    { supplierRef: 'SUP-OPO-01', status: 'APPROVED', orderDaysAgo: 5, currency: 'EUR', destination: WAREHOUSE_EU, lines: [{ sku: 'LT-BAG-TOTE', qty: 120 }, { sku: 'LT-WALLET-BF', qty: 250 }], taxRateBps: 2100 },
    { supplierRef: 'SUP-TUP-01', status: 'READY_TO_SHIP', orderDaysAgo: 14, currency: 'USD', destination: WAREHOUSE_US, lines: [{ sku: 'AP-TEE-ORG-M', qty: 2000 }, { sku: 'AP-HOOD-FLC-L', qty: 500 }], charges: 25000 },
    { supplierRef: 'SUP-MTY-01', status: 'READY_TO_SHIP', orderDaysAgo: 9, currency: 'USD', destination: WAREHOUSE_US, lines: [{ sku: 'ST-BRKT-90', qty: 12000 }] },
    { supplierRef: 'SUP-RTM-01', status: 'PARTIALLY_RECEIVED', orderDaysAgo: 30, currency: 'EUR', destination: WAREHOUSE_EU, lines: [{ sku: 'PK-BOX-40X30', qty: 8000 }], taxRateBps: 2100, receivedFraction: 0.5 },
    { supplierRef: 'SUP-SZX-01', status: 'RECEIVED', orderDaysAgo: 60, currency: 'USD', destination: WAREHOUSE_US, lines: [{ sku: 'EL-USB-C-HUB', qty: 300 }, { sku: 'EL-BT-SPK-02', qty: 100 }], receivedFraction: 1 },
    { supplierRef: 'SUP-TUP-01', status: 'CANCELLED', orderDaysAgo: 45, currency: 'USD', destination: WAREHOUSE_US, lines: [{ sku: 'AP-HOOD-FLC-L', qty: 800 }], notes: 'Cancelled — design change' },
  ];

  const pos: PurchaseOrderDoc[] = [];
  let poSeq = 0;
  for (const spec of poSpecs) {
    poSeq += 1;
    const orderDate = daysAgo(spec.orderDaysAgo);
    const lines = spec.lines.map((l) => {
      const p = product(l.sku);
      return { _id: new Types.ObjectId(), productId: p._id, sku: p.sku, description: p.name, quantity: l.qty, unitOfMeasure: p.unitOfMeasure, unitPriceMinor: l.price ?? p.defaultUnitCostMinor };
    });
    const totals = calculatePurchaseOrderTotals({ lines, taxRateBps: spec.taxRateBps ?? 0, additionalChargesMinor: spec.charges ?? 0 });
    const received = spec.receivedFraction ?? 0;
    const poNumber = `PO-${orderDate.getUTCFullYear()}-${String(poSeq).padStart(5, '0')}`;
    const statusDates: Record<string, unknown> = {};
    if (['APPROVED', 'READY_TO_SHIP', 'PARTIALLY_RECEIVED', 'RECEIVED'].includes(spec.status)) Object.assign(statusDates, { approvedAt: new Date(orderDate.getTime() + DAY_MS), approvedBy: adminId });
    if (['READY_TO_SHIP', 'PARTIALLY_RECEIVED', 'RECEIVED'].includes(spec.status)) statusDates.readyToShipAt = new Date(orderDate.getTime() + 3 * DAY_MS);
    if (spec.status === 'RECEIVED') statusDates.receivedAt = new Date(orderDate.getTime() + 20 * DAY_MS);
    if (spec.status === 'CANCELLED') Object.assign(statusDates, { cancelledAt: new Date(orderDate.getTime() + 2 * DAY_MS), cancellationReason: 'Design change' });
    const po = await PurchaseOrder.create({
      organizationId, poNumber, supplierId: suppliers[spec.supplierRef]!._id, orderDate,
      expectedDeliveryDate: new Date(orderDate.getTime() + 35 * DAY_MS),
      destination: spec.destination, currency: spec.currency,
      lines: lines.map((l, i) => ({ ...l, lineTotalMinor: totals.lineTotalsMinor[i], receivedQuantity: Math.round(l.quantity * received) })),
      subtotalMinor: totals.subtotalMinor, taxRateBps: spec.taxRateBps ?? 0, taxMinor: totals.taxMinor,
      additionalChargesMinor: totals.additionalChargesMinor, totalMinor: totals.totalMinor,
      notes: spec.notes, status: spec.status, createdBy: memberId, isDemo: true,
      receipts: received > 0 ? [{ receivedAt: new Date(orderDate.getTime() + 18 * DAY_MS), receivedBy: memberId, receivedByName: 'Sam Rivera (Demo Member)', note: 'Demo receipt', lines: lines.map((l) => ({ lineId: l._id, quantity: Math.round(l.quantity * received) })) }] : [],
      ...statusDates,
    });
    await AuditLog.collection.insertMany([
      { organizationId, entityType: 'PURCHASE_ORDER', entityId: po._id, action: 'CREATED', summary: `Purchase order ${poNumber} created as draft`, actorId: memberId, actorName: 'Sam Rivera (Demo Member)', createdAt: orderDate },
      ...(statusDates.approvedAt ? [{ organizationId, entityType: 'PURCHASE_ORDER', entityId: po._id, action: 'STATUS_APPROVED', summary: 'Approved by Alex Morgan (Demo Admin)', actorId: adminId, actorName: 'Alex Morgan (Demo Admin)', createdAt: statusDates.approvedAt }] : []),
      ...(statusDates.readyToShipAt ? [{ organizationId, entityType: 'PURCHASE_ORDER', entityId: po._id, action: 'STATUS_READY_TO_SHIP', summary: 'Marked ready to ship', actorId: memberId, actorName: 'Sam Rivera (Demo Member)', createdAt: statusDates.readyToShipAt }] : []),
      ...(statusDates.cancelledAt ? [{ organizationId, entityType: 'PURCHASE_ORDER', entityId: po._id, action: 'STATUS_CANCELLED', summary: 'Cancelled: Design change', actorId: adminId, actorName: 'Alex Morgan (Demo Admin)', createdAt: statusDates.cancelledAt }] : []),
    ]);
    pos.push(po);
  }
  await Counter.create({ organizationId, key: `PO-${NOW.getUTCFullYear()}`, seq: poSeq });

  // ---------------- Shipments ----------------
  const plans: ShipmentPlan[] = [];
  let seq = 0;
  const nextRef = () => `SHP-${NOW.getUTCFullYear()}-${String(++seq).padStart(6, '0')}`;

  // ~8 months of history: mostly delivered, ~20% delayed (late), a couple of exceptions.
  for (let i = 0; i < 46; i++) {
    const lane = LANES[i % LANES.length]!;
    // CEVA intentionally has few deliveries so its reliability shows as "insufficient history".
    const carrierPool = lane.carriers.filter((c) => c !== 'CEVA' || i % 9 === 0);
    const carrier = carrierPool[Math.floor(seededUnit(`carrier${i}`) * carrierPool.length)]!;
    const u = seededUnit(`outcome${i}`);
    const outcome: SimOutcome = u < 0.72 ? 'ON_TIME' : u < 0.92 ? 'DELAYED' : 'EXCEPTION';
    plans.push({ ref: nextRef(), lane, carrier, createdAt: daysAgo(240 - i * 4.6, (i * 5) % 11), stage: 'BOOKED', outcome, cancelled: i === 17 || i === 33 });
  }

  // Active shipments (tracking continues in real time via the simulator job).
  const poReceived = pos.find((p) => p.status === 'RECEIVED')!;
  const poPartial = pos.find((p) => p.status === 'PARTIALLY_RECEIVED')!;
  const poReady = pos.filter((p) => p.status === 'READY_TO_SHIP');
  const poLines = (po: PurchaseOrderDoc, fraction = 1) => ({
    _id: po._id, poNumber: po.poNumber,
    lines: po.lines.map((l) => ({ _id: l._id, description: l.description, quantity: Math.round(l.quantity * fraction), sku: l.sku, unitOfMeasure: l.unitOfMeasure })),
  });
  const active: Omit<ShipmentPlan, 'ref'>[] = [
    { lane: LANES[0]!, carrier: 'DHL', createdAt: daysAgo(1, 4), stage: 'BOOKED', outcome: 'ON_TIME' },
    { lane: LANES[1]!, carrier: 'FEDEX', createdAt: daysAgo(3), stage: 'BOOKED', outcome: 'DELAYED', purchaseOrder: poLines(poReady[0]!, 0.5) },
    { lane: LANES[2]!, carrier: 'DSV', createdAt: daysAgo(5, 6), stage: 'BOOKED', outcome: 'EXCEPTION' },
    { lane: LANES[5]!, carrier: 'KUEHNE_NAGEL', createdAt: daysAgo(52), stage: 'BOOKED', manualStuck: true },
    { lane: LANES[3]!, carrier: 'KUEHNE_NAGEL', createdAt: daysAgo(2, 6), stage: 'BOOKED', outcome: 'ON_TIME', purchaseOrder: poLines(poPartial, 0.5) },
    { lane: LANES[4]!, carrier: 'DSV', createdAt: daysAgo(6), stage: 'BOOKED', outcome: 'ON_TIME' },
    { lane: LANES[5]!, carrier: 'KUEHNE_NAGEL', createdAt: daysAgo(12), stage: 'BOOKED', outcome: 'ON_TIME' },
    { lane: LANES[6]!, carrier: 'FEDEX', createdAt: daysAgo(0, 5), stage: 'BOOKED', outcome: 'ON_TIME' },
    { lane: LANES[4]!, carrier: 'DSV', createdAt: daysAgo(0, 3), stage: 'QUOTED', purchaseOrder: poLines(poReady[1]!, 1) },
    { lane: LANES[0]!, carrier: 'DHL', createdAt: daysAgo(0, 1), stage: 'DRAFT' },
    { lane: LANES[0]!, carrier: 'FEDEX', createdAt: daysAgo(58), stage: 'BOOKED', outcome: 'ON_TIME', purchaseOrder: poLines(poReceived, 1) },
  ];
  for (const a of active) plans.push({ ...a, ref: nextRef() });

  for (const plan of plans) await createDemoShipment(organizationId, adminId, suppliers, plan);
  await Counter.create({ organizationId, key: `SHP-${NOW.getUTCFullYear()}`, seq });

  // Alerts from the real rule engine (overdue / stuck / carrier exceptions on active shipments).
  const rules = await rulesForOrg(organizationId);
  const monitored = await Shipment.find({ organizationId, status: { $in: ['BOOKED', 'PICKED_UP', 'IN_TRANSIT', 'OUT_FOR_DELIVERY', 'DELAYED', 'EXCEPTION'] } });
  for (const s of monitored) await evaluateShipmentAlerts(s, rules, NOW);
  await Alert.updateMany({ organizationId }, { $set: { isDemo: true } });

  return { suppliers: supplierDocs.length, products: productDocs.length, purchaseOrders: pos.length, shipments: plans.length };
}

async function seedNorthwind(organizationId: Types.ObjectId) {
  // A small second tenant used to demonstrate (and test) organisation isolation.
  await Supplier.create({ organizationId, supplierRef: 'NW-SUP-01', name: 'Nordic Timber AB (fictional)', email: 'sales@nordictimber.example', country: 'SE', city: 'Gothenburg', isDemo: true });
  await Product.create({ organizationId, sku: 'NW-OAK-PLANK', name: 'Oak Plank 2m', unitOfMeasure: 'EA', defaultUnitCostMinor: 2400, currency: 'EUR', isDemo: true });
}

async function main() {
  await mongoose.connect(env.MONGODB_URI);
  await Promise.all(mongoose.modelNames().map((n) => mongoose.model(n).createIndexes()));
  console.log('Resetting demo data…');
  await resetDemoData();
  const { demo, northwind, users } = await seedOrgsAndUsers();
  const summary = await seedDemoOrg(demo._id, users['alex.morgan@fluxora.test']!, users['sam.rivera@fluxora.test']!);
  await seedNorthwind(northwind._id);
  console.log('Seed complete:', summary);
  console.log('Demo sign-in (requires AUTH_DEV_LOGIN_ENABLED=true):');
  for (const u of DEMO_USERS) console.log(`  ${u.email}  (${u.role} — ${u.org})`);
  await mongoose.disconnect();
}

main().catch(async (err) => {
  console.error(err);
  await mongoose.disconnect();
  process.exit(1);
});
